      id: 'lagos-benagil-cave', city: 'lagos', category: 'nature', spot: 'insta', lat: 37.0871, lng: -8.4255, image: 'W9ZIbpOzcoA',
      rating: 4.8, reviews: 29700, tags: ['photo', 'kayak', 'beaches'], price: { kind: 'from', amount: 25, currency: 'EUR' },
      address: 'Praia de Benagil, 8400-153 Lagoa',
      text: {
        ru: { name: 'Грот Бенагил', description: 'Огромная морская пещера с круглым «окном» в своде, через которое солнечный луч падает на песчаный пляж внутри. Главная открытка Алгарве.', tip: 'Заплывайте на лодке или каяке с лицензированным гидом утром, когда свет падает в окно сверху; высаживаться на пляж внутри грота сейчас запрещено.' },
        en: { name: 'Benagil Cave', description: 'A huge sea cave with a round “window” in its roof through which a shaft of sunlight falls on the sandy beach inside. The Algarve’s signature postcard.', tip: 'Go in by boat or kayak with a licensed guide in the morning, when the light pours through the opening; landing on the beach inside the cave is now prohibited.' },
        es: { name: 'Cueva de Benagil', description: 'Una enorme cueva marina con una «ventana» redonda en la bóveda por la que un rayo de sol cae sobre la playa de arena del interior. La postal más famosa del Algarve.', tip: 'Entra en barca o kayak con un guía autorizado por la mañana, cuando la luz entra por la abertura; ahora está prohibido desembarcar en la playa de la cueva.' },
        de: { name: 'Benagil-Höhle', description: 'Eine riesige Meereshöhle mit einem runden „Fenster“ in der Decke, durch das ein Sonnenstrahl auf den Sandstrand im Inneren fällt. Das bekannteste Postkartenmotiv der Algarve.', tip: 'Fahr morgens mit Boot oder Kajak und lizenziertem Guide hinein, wenn das Licht durch die Öffnung fällt; an dem Strand in der Höhle anzulanden ist inzwischen verboten.' },
        fr: { name: 'Grotte de Benagil', description: 'Une immense grotte marine percée d’une « fenêtre » ronde dans sa voûte, par laquelle un rai de soleil tombe sur la plage de sable intérieure. La carte postale emblématique de l’Algarve.', tip: 'Entrez en bateau ou en kayak avec un guide agréé le matin, quand la lumière tombe par l’ouverture ; débarquer sur la plage de la grotte est désormais interdit.' },
        it: { name: 'Grotta di Benagil', description: 'Un’enorme grotta marina con una «finestra» rotonda nella volta da cui un raggio di sole cade sulla spiaggia di sabbia all’interno. La cartolina simbolo dell’Algarve.', tip: 'Entra in barca o in kayak con una guida autorizzata al mattino, quando la luce piove dall’apertura; sbarcare sulla spiaggia della grotta ora è vietato.' },
      },
